(40,'Chon Buri','TH',38),
(41,'Phuket','TH',38),
(42,'Adjara','GE',42),
(43,'Yerevan','AM',43),
(44,'Van','TR',32),
(45,'Tbilisi','GE',42),
(46,'Istanbul','TR',32),
(47,'Dubai','AE',37),
(48,'Baghdad','IQ',34),
(49,'Karbala','IQ',34),
(50,'Najaf','IQ',34),
(51,'Antalya','TR',32),
(52,'England','GB',52),
(53,'Moscow','RU',53),
(54,'Baladiyat ad Dawhah','QA',54),
